async function downloadShiftTrendsExcel(){
  try{
    const data=window._lastTrendExport;
    if(!data||!data.cols||!data.rows||!data.rows.length){
      try{toast(typeof L==="function"?L("⚠️ कोई ट्रेंड डेटा नहीं","⚠️ No trend data"):"⚠️ No trend data")}catch(e){}
      return;
    }
    try{toast(typeof L==="function"?L("⬇️ Trend Excel…","⬇️ Trend Excel…"):"⬇️ Trend Excel…")}catch(e){}
    if(typeof ensureXlsx==="function"){try{await ensureXlsx()}catch(e){}}
    if(typeof XLSX==="undefined"){
      try{toast(L('❌ एक्सेल लाइब्रेरी लोड नहीं हुई','❌ Excel library not loaded'))}catch(e){}
      return;
    }
    const headers=["Name","Emp ID"].concat(data.cols.map(c=>c.label||c.key));
    const aoa=[headers];
    data.rows.forEach(r=>{
      const row=[r.name||"",r.empId||""];
      data.cols.forEach(c=>{const v=r.counts&&r.counts[c.key];row.push(v>0?v:"")});
      aoa.push(row);
    });
    // totals row
    const tot=["TOTAL",""];
    data.cols.forEach(c=>{let s=0;data.rows.forEach(r=>{s+=(r.counts&&r.counts[c.key])||0});tot.push(s||"")});
    aoa.push(tot);
    const ws=XLSX.utils.aoa_to_sheet(aoa);
    const wb=XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb,ws,"Shift Trends");
    const safe=(data.rangeLabel||"trends").replace(/[^a-zA-Z0-9]+/g,"_").slice(0,40);
    XLSX.writeFile(wb,"ManPower_Shift_Trends_"+safe+".xlsx");
    try{toast(typeof L==="function"?L("✅ Trend Excel डाउनलोड हो गया","✅ Trend Excel downloaded"):"✅ Trend Excel downloaded")}catch(e){}
  }catch(err){
    console.error("downloadShiftTrendsExcel",err);
    try{toast(L("❌ ","❌ ")+(err&&err.message||err))}catch(e){}
  }
}
