  let typeOpts=[{value:"Casual Leave",code:"CL",label:L("CL — Casual Leave","CL — Casual Leave")},{value:"Sick Leave",code:"SL",label:L("SL — Sick Leave","SL — Sick Leave")},{value:"Emergency Leave",code:"EML",label:L("EML — Emergency Leave","EML — Emergency Leave")},{value:"Earned Leave",code:"EL",label:L("EL — Earned Leave","EL — Earned Leave")},{value:"C-Off",code:"CO",label:L("C-Off — Compensatory Off","C-Off — Compensatory Off")}];
