async function openHistoricalOverrideReview(cursor = null, query = '') {
  if (!isAdmin()) return;
  try {
    const result = await window._fbCall('readHistoricalOverrideReview', {cursor,query});
    const labels = {
      linked:L('सत्यापित लिंक','Reviewed link'), conflict:L('रिकॉर्ड में अंतर','Conflicting values'),
      archive:L('संग्रहीत कर्मचारी','Archived employee'), unresolved:L('सत्यापन बाकी','Needs review'),
      quarantined:L('समीक्षा के लिए अलग','Held for review'),
      approve:L('स्वीकृत','Approved'),quarantine:L('अलग रखा','Held'),rollback:L('पूर्ववत','Rolled back')
    };
    const counts = Object.entries(result.counts).map(([key,count])=>labels[key] + ' ' + count).join(' · ');
    const body = result.items.map((item,i)=>`
      <li class="identity-review-record">
        <strong>${escHtml(item.key)}</strong><br>
        ${labels[item.status]} · ${escHtml(item.shift || '')}
        ${item.employeeId ? ' · ' + escHtml(item.employeeId) : ''}
        ${item.suggestion ? '<p>' + L('संग्रह से सत्यापित कर्मचारी कुंजी','Verified archive predecessor') + ' · ' + escHtml(item.suggestion.employeeId) + '</p>' : ''}
        <details><summary>${L('पहचान की समीक्षा करें','Review identity')}</summary>
          <label>${L('कर्मचारी कुंजी','Employee key')}<input class="inp-field" data-employee value="${escHtml(item.employeeId || item.suggestion?.employeeId || '')}"></label>
          <label>${L('साक्ष्य या कारण','Evidence or reason')}<textarea class="inp-field" data-reason maxlength="300" rows="2"></textarea></label>
          <button type="button" data-action="approve" data-row="${i}">${L('लिंक स्वीकृत करें','Approve link')}</button>
          ${item.link ? '' : '<button type="button" data-action="quarantine" data-row="' + i + '">' + L('समीक्षा के लिए अलग रखें','Hold for review') + '</button>'}
          ${(item.audit || []).map(entry=>`<p>${escHtml(labels[entry.action] || entry.action)} · ${escHtml(entry.at)} · ${escHtml(entry.reason)}
            ${entry.canRollback ? '<button type="button" data-action="rollback" data-row="' + i + '">' + L('पूर्ववत करें','Roll back') + '</button>' : ''}</p>`).join('')}
          <p role="status" data-review-status></p>
        </details>
      </li>`).join('');
    openModal(`<div class="modal-handle"></div>
      <div class="modal-title">${L('ऐतिहासिक शिफ्ट रिकॉर्ड','Historical shift records')}</div>
      <form id="historicalReviewSearch"><label>${L('रिकॉर्ड या कर्मचारी कुंजी खोजें','Search record or employee key')}<input class="inp-field" name="query" value="${escHtml(query)}"></label>
        <button type="submit" class="cancel-btn">${L('खोजें','Search')}</button>
      </form>
      <p>${counts}</p>
      <ul id="historicalReviewList" class="identity-review-list">${body}</ul>
      ${result.next ? `<button id="historicalReviewNext" type="button" class="submit-btn">${L('अगले रिकॉर्ड','Next records')}</button>` : ''}
      <button type="button" class="cancel-btn" onclick="closeModal()">${L('बंद करें','Close')}</button>`);
    document.getElementById('historicalReviewSearch').onsubmit = event => {
      event.preventDefault();
      openHistoricalOverrideReview(null,event.currentTarget.elements.query.value);
    };
    if (result.next) document.getElementById('historicalReviewNext').onclick = () => openHistoricalOverrideReview(result.next,query);
    for (const button of document.querySelectorAll('#historicalReviewList [data-action]')) {
      button.onclick = async () => {
        const item = result.items[Number(button.dataset.row)];
        const record = button.closest('details');
        const status = record.querySelector('[data-review-status]');
        const reason = record.querySelector('[data-reason]').value.trim();
        if (reason.length < 8) { status.textContent=L('कम से कम आठ अक्षरों का कारण दें','Enter at least eight characters of evidence or reason'); return; }
        button.disabled = true;
        try {
          await window._fbCall('updateIdentityReview',{
            key:item.key,action:button.dataset.action,reason,
            employeeId:record.querySelector('[data-employee]').value.trim(),
            expectedShift:item.sourceValue ?? item.shift,expectedLink:item.link || null,
            expectedQuarantine:item.quarantine || null,auditId:item.audit?.find(entry=>entry.canRollback)?.id || null
          });
          await openHistoricalOverrideReview(cursor,query);
        } catch (error) { status.textContent=error.message; button.disabled=false; }
      };
    }
  } catch (error) {
    toast(L('ऐतिहासिक रिकॉर्ड नहीं खुले: ','Could not open historical records: ') + (error.message || ''));
  }
}

function putImportedExcelShift(months, month, employee, index, input) {
  if (input == null || String(input).trim() === '') return;
  const code = _normShiftCode(input);
  if (!code) throw new Error(L('एक्सेल शिफ्ट कोड अमान्य है','Invalid shift code in Excel'));
  const monthRows = months[month] ||= Object.create(null);
  const row = monthRows[employee] ||= Object.create(null);
  if (Object.hasOwn(row,index) && row[index] !== code) {
    throw new Error(L('एक कर्मचारी और तारीख के लिए अलग शिफ्ट मिलीं','Conflicting shifts for one employee and date'));
  }
  row[index] = code;
}

function planExcelScheduleImport(months, roster) {
  const codes = new Map();
  const ids = new Map();
  for (const employee of roster) {
    if (!employee?.id) continue;
    ids.set(employee.id, employee);
    const code = String(employee.empId || '').trim().toUpperCase();
    if (code) codes.set(code, codes.has(code) ? null : employee);
  }
  const patch = {};
  for (const [month, rows] of Object.entries(months)) {
    if (!/^\d{4}_(0[1-9]|1[0-2])$/.test(month)) throw new Error('Invalid schedule month');
    const [year, number] = month.split('_').map(Number);
    const maxDay = new Date(Date.UTC(year, number, 0)).getUTCDate();
    for (const [key, shifts] of Object.entries(rows)) {
      const direct = ids.get(key);
      const byCode = codes.get(key.trim().toUpperCase());
      if ((!direct && !byCode) || (direct && byCode && direct.id !== byCode.id)) {
        throw new Error(L('पहले टीम में कर्मचारी की पहचान सत्यापित करें।','Verify the employee in Team before importing the schedule.'));
      }
      const employee = direct || byCode;
      for (const [index, shift] of Object.entries(shifts || {})) {
        if (shift == null || shift === '') continue;
        if (!/^\d+$/.test(index) || Number(index) >= maxDay) throw new Error('Invalid schedule date');
        const path = month + '/' + employee.id + '/' + index;
        if (Object.hasOwn(patch,path) && patch[path] !== shift) throw new Error('Conflicting Excel entries for one employee and date');
        patch[path] = shift;
      }
    }
  }
  return {patch};
}
